 static BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;static string dir;static int count;
 static T F<T>(object o,string n){return (T)o.GetType().GetField(n,flags).GetValue(o);}static void Set(object o,string n,object v){o.GetType().GetField(n,flags).SetValue(o,v);}static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,flags).Invoke(o,a);}static void Check(bool v,string why){count++;if(!v)throw new Exception(why);}static void Snap(Form f,string name){Application.DoEvents();if(f is MainForm){var p=F<PreviewPanel>(f,"preview");File.AppendAllText(Path.Combine(dir,"render-state.txt"),name+" shapes="+(p.Scene==null?-1:p.Scene.Shapes.Count)+" selected="+p.SelectedIndex+" label="+p.LabelRectangle()+" pos="+p.ElementRectangle(-1)+"\r\n");using(var bitmap=new Bitmap(p.Width,p.Height)){p.DrawToBitmap(bitmap,p.ClientRectangle);var rect=p.LabelRectangle();int ink=0;for(int y=rect.Top+2;y<rect.Bottom-2;y+=8)for(int x=rect.Left+2;x<rect.Right-2;x+=8)if(bitmap.GetPixel(x,y).R<50&&bitmap.GetPixel(x,y).G<50&&bitmap.GetPixel(x,y).B<50)ink++;Check(ink>20,"label content remains rendered: "+name);bitmap.Save(Path.Combine(dir,name+"-canvas.png"));}}using(var b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(Path.Combine(dir,name+".png"));}}
 [STAThread]static void Main(string[] args){dir=args[0];Directory.CreateDirectory(dir);try{Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Run();File.WriteAllText(Path.Combine(dir,"passed.txt"),"PASS "+count+" assertions: native frame/styles/title/accessibility; tooltip timing; responsive tools and overflow; repeated minimize/restore and maximize; caption/theme updates reuse label scene; close cancellation; simulated 100/125/150/200% toolbar geometry. Real monitor DPI transitions, Snap gestures, native caption tooltip, non-client DWM colors, system menu and screen reader need interactive Windows verification.");}catch(Exception e){File.WriteAllText(Path.Combine(dir,"failed.txt"),e.ToString());Environment.ExitCode=1;}}
 static void Run(){using(var f=new MainForm(Path.Combine(dir,"prefs.xml"))){f.Icon=new Icon(Path.Combine(Path.GetDirectoryName(typeof(MainForm).Assembly.Location),@"..\..\assets\app.ico"));f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);f.Show();Application.DoEvents();var studio=F<TableLayoutPanel>(f,"studio");var tools=F<FlowLayoutPanel>(f,"editorTools");var preview=F<PreviewPanel>(f,"preview");var scene=preview.Scene;Check(f.FormBorderStyle==FormBorderStyle.Sizable&&f.ControlBox&&f.MaximizeBox&&f.MinimizeBox,"native frame and controls retained");Check(f.Text.Contains("ND LabelDesigner — prelease  |  ")&&f.Text.Contains("Nová etiketa"),"single native title");foreach(Control c in F<Control>(f,"headerSurface").Controls)Check(!(c is Label),"no duplicate client title");Check(studio.Padding.Top==0,"no black top band");Check(!F<bool>(f,"keyboardHeaderFocus"),"no startup keyboard hint");var tips=F<UiToolTip>(f,"headerTips");Check(!tips.ShowAlways&&tips.AutoPopDelay==3000&&tips.InitialDelay==400,"bounded tooltip duration");
 for(int i=0;i<8;i++){f.WindowState=FormWindowState.Minimized;Application.DoEvents();f.WindowState=FormWindowState.Normal;f.Size=new Size(i%2==0?1024:1440,800);Application.DoEvents();Call(f,"UpdateToolbarLayout");Check(studio.RowStyles[1].Height<110,"no ballooning toolbar after restore");Check(F<SplitContainer>(f,"tableSplit").Height>300,"editor retains space");}f.Size=new Size(1024,640);Call(f,"UpdateToolbarLayout");foreach(Control c in F<FlowLayoutPanel>(f,"headerCommands").Controls)Check(c.Visible,"compact icons remain available");Snap(f,"dark-minimum");f.Size=new Size(1440,900);Call(f,"UpdateToolbarLayout");Check(F<FlowLayoutPanel>(f,"headerCommands").Visible,"restore header actions");
 Set(f,"settingsPath",Path.Combine(dir,new string('A',180)+".ean.xml"));Set(f,"dirty",true);Call(f,"UpdateWindowTitle");Check(f.Text.Contains("|  • ")&&f.AccessibleName.Contains("neuložené zmeny"),"dirty title and verbal accessible state");Check(Object.ReferenceEquals(scene,preview.Scene),"title does not rebuild preview");Call(f,"ToggleTheme");Check(Object.ReferenceEquals(scene,preview.Scene),"theme does not rebuild preview");Snap(f,"light-long-title");Call(f,"ToggleTheme");Snap(f,"dark-long-title");Call(f,"OnDeactivate",EventArgs.Empty);Check(!F<bool>(f,"windowActive"),"inactive header state");Snap(f,"dark-inactive");Call(f,"OnActivated",EventArgs.Empty);Check(F<bool>(f,"windowActive"),"active header state");f.WindowState=FormWindowState.Maximized;Application.DoEvents();Check(f.WindowState==FormWindowState.Maximized,"maximize");f.WindowState=FormWindowState.Normal;Application.DoEvents();Check(studio.RowStyles[1].Height<110,"restore from maximized");
 // Exercise the existing unsaved-change guard. A test timer cancels only the test-owned modal.
 bool cancelled=false;using(var timer=new Timer{Interval=100}){timer.Tick+=delegate{foreach(Form d in Application.OpenForms)if(d!=f){d.DialogResult=DialogResult.Cancel;d.Close();cancelled=true;timer.Stop();break;}};timer.Start();Check(!(bool)Call(f,"CanDiscard"),"close guard cancels");}Check(cancelled&&!f.IsDisposed,"document remains after cancellation");
